describe('Mobile Layout Horizontal Scroll Disabled', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should disable horizontal scrolling on mobile layout', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Verify horizontal scrollbar is visible initially
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-x', 'scroll');

    // Intercept the scroll event
    cy.intercept('scroll', {
      method: 'POST',
      url: '/api/scroll-event',
      statusCode: 200,
    }).as('scrollEvent');

    // Scroll horizontally
    cy.get('[data-testid="main-container"]').scrollTo('left', -1000);

    // Verify scroll event was triggered
    cy.wait('@scrollEvent');

    // Verify horizontal scrollbar is still visible
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-x', 'scroll');

    // Verify content is still visible and not cut off
    cy.get('[data-testid="content-item"]').should('be.visible');

    // Verify horizontal scrollbar is disabled
    cy.get('[data-testid="main-container"]').should('not.have.css', 'overflow-x');

    // Verify vertical scroll is still enabled
    cy.get('[data-testid="main-container"]').scrollTo('top', -1000);
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-y', 'scroll');
  });

  it('should handle edge case where horizontal scroll is still enabled', () => {
    // Set viewport to mobile dimensions
    cy.viewport('iphone-x');

    // Verify horizontal scrollbar is visible
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-x', 'scroll');

    // Scroll horizontally
    cy.get('[data-testid="main-container"]').scrollTo('left', -1000);

    // Verify scroll event was triggered
    cy.wait('@scrollEvent');

    // Verify horizontal scrollbar is still visible
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-x', 'scroll');

    // Verify content is still visible and not cut off
    cy.get('[data-testid="content-item"]').should('be.visible');

    // Verify horizontal scrollbar is still enabled (edge case)
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-x', 'scroll');

    // Verify vertical scroll is still enabled
    cy.get('[data-testid="main-container"]').scrollTo('top', -1000);
    cy.get('[data-testid="main-container"]').should('have.css', 'overflow-y', 'scroll');

    // Verify no horizontal scrollbar appears when scrolling vertically
    cy.get('[data-testid="main-container"]').scrollTo('top', -1000);
    cy.get('[data-testid="main-container"]').should('not.have.css', 'overflow-x');
  });
});
